def validate_services(row,by_kind):
    first=row['snapshots'][0];returned=by_kind['scope_callback_return'];d=returned['diagnostic']
    global_mutex=hex(int(d['global_lock'],16)+8);selected_mutex=hex(int(d['entry'],16)+8)
    expected=[('pthread_mutex_lock_route','0x347f00',global_mutex),('actual_Bionic_mutex_lock_entry','libc:0x68cf8',global_mutex),
        ('actual_Bionic_malloc_route','0x347fd0','0x30'),('actual_Bionic_malloc_entry','libc:0x1bb08','0x30'),
        ('pthread_mutex_unlock_route','0x347f10',global_mutex),('actual_Bionic_mutex_unlock_entry','libc:0x68d5c',global_mutex),
        ('pthread_mutex_lock_route','0x347f00',selected_mutex),('actual_Bionic_mutex_lock_entry','libc:0x68cf8',selected_mutex)]
    assert [(s['kind'],s['PC'],s['argument']) for s in row['services']]==expected
