def validate_next_call(row,data,last):
    call=row['next_VM_call'];returned=row['snapshots'][-2]
    assert call['index']==row['instruction_observations'] and call['callsite_offset']==hex(VM_CALL) and call['VM_cursor_offset']==last['VM_cursor']=='0x10a270'
