    assert call['allocation_request_size']==4 and call['static_expected_target_arguments']=={'x0':'0x4'}
    assert call['result_slot_address']==hex(int(call['descriptor_address'],16)+16)=='0x7004cdb8'
    assert call['wrapper_code_hex']==data['static_code']['main:'+hex(NEXT_WRAPPER)]['hex']
    assert len(bytes.fromhex(call['wrapper_code_hex']))==NEXT_WRAPPER_SIZE==28 and raw_hash(bytes.fromhex(call['wrapper_code_hex']))==call['wrapper_code_sha256']
